import {kgFrom,number} from './calculations.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const parklandSource='https://www.ncbi.nlm.nih.gov/books/NBK609549/';
export const shockSource='https://pubmed.ncbi.nlm.nih.gov/8092595/';
// S505 p. 143: preserve the printed height labels and 50 mg/mL columns.
export const ketaminePainTable=[
 {height:'<4′11″',ivMg:7.5,ivMl:0.15,imMg:30,imMl:0.6},
 {height:'5′–5.5″',ivMg:10,ivMl:0.2,imMg:40,imMl:0.8},
 {height:'5.5′–5′11″',ivMg:15,ivMl:0.3,imMg:60,imMl:1.2},
 {height:'6′–6′5″',ivMg:17.5,ivMl:0.35,imMg:70,imMl:1.4},
 {height:'>6′5″',ivMg:20,ivMl:0.4,imMg:80,imMl:1.6}
];
export function painPanel(fields,source,icon){return `<details class="burns-panel ketamine-panel" data-clinical-open="ketamine" ${fields['ketamine-open']?'open':''}><summary><span class="burns-icon">${icon('syringe')}</span><span><b>Ketamine · pain</b></span><span class="burns-expand">+</span></summary><div class="burns-content trauma-pain"><div class="clinical-links">${source('PAIN DOSING · S505',143)}</div><div class="pain-stock"><b>500 mg / 10 mL</b><span>50 mg/mL · age 16+</span></div><table class="pain-table"><caption>Height-based dosing · ideal body weight</caption><thead><tr><th scope="col">Height</th><th scope="col" class="pain-iv">IV</th><th scope="col" class="pain-im">IM</th></tr></thead><tbody>${ketaminePainTable.map(r=>`<tr><th scope="row">${esc(r.height)}</th><td class="pain-iv"><b>${r.ivMl} <span>mL</span></b><small>${r.ivMg} mg</small></td><td class="pain-im"><b>${r.imMl} <span>mL</span></b><small>${r.imMg} mg</small></td></tr>`).join('')}</tbody></table><p class="pain-administration"><b>IV:</b> Slow push over 1 minute, or infuse in 100 mL NS / D5W over 15 minutes.</p><p class="clinical-help">Height labels as printed in S505. Monitor pulse oximetry, respirations, BP, and mental status.</p></div></details>`;}
export const ruleOfNines=[['Head / neck',9,18],['Anterior trunk',18,18],['Posterior trunk',18,18],['Each arm',9,9],['Each leg',18,14],['Genitals / perineum',1,null]];
export function shockIndex(hr,sbp){const h=number(hr),s=number(sbp);const value=h>0&&s>0?h/s:null;return Number.isFinite(value)?value:null;}
export function parkland(weight,unit,tbsa){const kg=kgFrom(weight,unit),area=number(tbsa);if(kg===null||area===null||area<=0||area>100)return null;const total=4*kg*area;if(!Number.isFinite(total))return null;return {kg,total,first8:total/2,next16:total/2};}
const display=n=>Number(n.toFixed(1)).toLocaleString('en-US',{maximumFractionDigits:1});
const clock=time=>new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(time));
export function sickAlertActions(fields,icon){const at=fields['sick-alert-at'],recorded=Number.isFinite(at)&&at>0;return `<section class="sick-alert-events" aria-label="Relevant alert timestamp"><div class="trauma-event"><button class="trauma-event-button" data-clinical-event="sick-alert" aria-label="CALLED RELEVANT ALERT" ${recorded?'disabled':''}>${icon('pulse')}<span><b>CALLED RELEVANT ALERT</b><small>${recorded?'Recorded':'Tap to timestamp'}</small></span></button><p class="alert-early-reminder"><b>CALL EARLY.</b> Notify the receiving hospital as soon as the relevant alert is identified.</p><div class="trauma-event-time" role="status">${recorded?`<time datetime="${new Date(at).toISOString()}">Alert called · ${clock(at)}</time><button data-clear-clinical-event="sick-alert" aria-label="Clear relevant alert timestamp">Clear time</button>`:''}</div></div></section>`;}
export function traumaActions(fields,source,icon){return `<section class="trauma-events" aria-label="Trauma timestamps">${[['alert','Called trauma alert','trauma-alert-at','Record when the alert is called.'],['txa','GIVE TXA','trauma-txa-at','Tap when TXA starts to record the time.']].map(([event,label,key,hint])=>{const at=fields[key],recorded=Number.isFinite(at)&&at>0;return `<div class="trauma-event"><button class="trauma-event-button" data-trauma-event="${event}" aria-label="${label}" ${recorded?'disabled':''}>${icon(event==='alert'?'pulse':'syringe')}<span><b>${label}</b><small>${recorded?'Recorded':'Tap to timestamp'}</small></span></button>${event==='alert'?'<p class="alert-early-reminder"><b>CALL EARLY.</b> Cell reception typically drops halfway through the drive to UCMC ER.</p>':''}<div class="trauma-event-time" role="status">${recorded?`<time datetime="${new Date(at).toISOString()}">${event==='txa'?'TXA started':'Alert called'} · ${clock(at)}</time><button data-clear-trauma-event="${event}" aria-label="Clear ${event==='txa'?'TXA':'trauma alert'} timestamp">Clear time</button>`:`<span>${hint}</span>`}</div>${event==='txa'?`<div class="txa-links">${source('TXA CRITERIA · S506',144)}${source('TXA EXCLUSIONS · S506',145)}</div>`:''}</div>`;}).join('')}<p class="trauma-event-help">Confirm TXA criteria, exclusions, and injury time before administration. Times record your tap and stay with this encounter.</p></section>`;}
export function shockPanel(fields,source,icon){const value=shockIndex(fields['shock-hr'],fields['shock-sbp']);return `<section class="panel shock-panel" aria-labelledby="shock-title"><div class="section-top"><h2 id="shock-title">${icon('pulse')} Shock index</h2><span class="clinical-formula">HR ÷ systolic BP</span></div><div class="shock-fields"><label class="field" for="shock-hr">Heart rate · bpm<input id="shock-hr" data-clinical-field="shock-hr" type="number" min="0" step="any" inputmode="decimal" value="${esc(fields['shock-hr'])}" placeholder="e.g. 120"></label><label class="field" for="shock-sbp">Systolic BP · mmHg<input id="shock-sbp" data-clinical-field="shock-sbp" type="number" min="0" step="any" inputmode="decimal" value="${esc(fields['shock-sbp'])}" placeholder="e.g. 100"></label><div class="shock-result" role="status"><span>SHOCK INDEX</span><strong>${value===null?'—':value.toFixed(2)}</strong></div></div><p class="clinical-help">${value===null?'Enter a heart rate and systolic BP greater than zero.':'Use with perfusion, vital-sign trends, and age.'}</p><div class="clinical-links">${source('SHOCK · SB205',53)}<a class="clinical-reference" href="${shockSource}" target="_blank" rel="noopener">Formula reference ↗</a></div></section>`;}
export function burnsPanel(fields,source,icon){const result=parkland(fields['burn-weight'],fields['burn-unit']||'kg',fields['burn-tbsa']);return `<details class="burns-panel" data-clinical-open="burns" ${fields['burns-open']?'open':''}><summary><span class="burns-icon">${icon('burns')}</span><span><b>Burns</b></span><span class="burns-expand">+</span></summary><div class="burns-content"><div class="clinical-links">${source('BURN PROTOCOL · S502',139)}${source('AIRWAY · T705',189)}</div><section class="burn-priorities"><ul><li>Protect the airway; assess smoke inhalation and respiratory distress.</li><li>Stop the burning process; remove affected clothing and constricting jewelry.</li><li>Turn up the heat. Cover burns with a clean, dry sheet.</li><li>Consider CO / cyanide exposure.</li><li>Provide pain care.</li></ul></section><section class="burn-rule"><div class="section-top"><h2>Rule of 9s</h2><span class="clinical-formula">% of total body surface area</span></div><p class="clinical-help">Count partial- and full-thickness burns only.</p><div class="burn-table-wrap"><table class="burn-table"><thead><tr><th>Region</th><th>Adult</th><th>Child · S502</th></tr></thead><tbody>${ruleOfNines.map(([region,adult,child])=>`<tr><td>${region}</td><td>${adult}%</td><td>${child===null?'Not listed':child+'%'}</td></tr>`).join('')}</tbody></table></div><p class="clinical-help">The patient’s whole palmar hand surface is approximately 1%. Use age-appropriate assessment for children.</p></section><section class="parkland-section"><div class="section-top"><h2>Parkland formula</h2></div><p class="parkland-formula">4 mL × weight (kg) × % TBSA</p><div class="parkland-fields"><label class="field" for="burn-weight">Patient weight<div class="weight-entry"><input id="burn-weight" data-clinical-field="burn-weight" type="number" min="0" step="any" inputmode="decimal" value="${esc(fields['burn-weight'])}" placeholder="Weight"><select id="burn-unit" data-clinical-field="burn-unit" aria-label="Burn weight unit"><option value="kg" ${fields['burn-unit']!=='lb'?'selected':''}>kg</option><option value="lb" ${fields['burn-unit']==='lb'?'selected':''}>lb</option></select></div></label><label class="field" for="burn-tbsa">Partial / full-thickness burn · % TBSA<input id="burn-tbsa" data-clinical-field="burn-tbsa" type="number" min="0" max="100" step="any" inputmode="decimal" value="${esc(fields['burn-tbsa'])}" placeholder="e.g. 20"></label></div><div class="parkland-result" role="status">${result?`<div><span>FIRST 24 HOURS</span><strong>${display(result.total)} <small>mL</small></strong></div><div><span>FIRST 8 HOURS · ½</span><strong>${display(result.first8)} <small>mL</small></strong></div><div><span>NEXT 16 HOURS · ½</span><strong>${display(result.next16)} <small>mL</small></strong></div>`:''}</div><p class="burn-field-plan">Use <b>S502</b> for field treatment and age-based crystalloid rates.</p><a class="clinical-reference" href="${parklandSource}" target="_blank" rel="noopener">Parkland reference · WHO ↗</a></section></div></details>`;}
export function bindClinicalTools(getState,save,render){
 function refresh(el){const y=window.scrollY,id=el?.id;render();window.scrollTo(0,y);if(id)document.getElementById(id)?.focus({preventScroll:true});}
 document.addEventListener('input',e=>{if(e.target.dataset.clinicalField&&e.target.tagName==='INPUT'){getState().fields[e.target.dataset.clinicalField]=e.target.value;save();refresh(e.target);}});
 document.addEventListener('change',e=>{if(e.target.dataset.clinicalField&&e.target.tagName==='SELECT'){getState().fields[e.target.dataset.clinicalField]=e.target.value;save();refresh(e.target);}});
 document.addEventListener('toggle',e=>{const panel=e.target.dataset?.clinicalOpen;if(['burns','ketamine','pediatric-meds','sedation-ketamine','sedation-midazolam'].includes(panel)){getState().fields[`${panel}-open`]=e.target.open;save();}},true);
 document.addEventListener('click',e=>{const summary=e.target.closest('details[data-clinical-open]>summary');if(summary){const details=summary.parentElement,panel=details.dataset.clinicalOpen;if(['burns','ketamine','pediatric-meds','sedation-ketamine','sedation-midazolam'].includes(panel)){getState().fields[`${panel}-open`]=!details.open;save();}}const b=e.target.closest('button');if(!b)return;const event=b.dataset.clinicalEvent||b.dataset.clearClinicalEvent||b.dataset.traumaEvent||b.dataset.clearTraumaEvent;const key={alert:'trauma-alert-at',txa:'trauma-txa-at','sick-alert':'sick-alert-at'}[event];if(!key)return;const fields=getState().fields,clearing=Boolean(b.dataset.clearClinicalEvent||b.dataset.clearTraumaEvent);if(clearing)delete fields[key];else if(!fields[key])fields[key]=Date.now();save();refresh();const attribute=event==='sick-alert'?(clearing?'data-clinical-event':'data-clear-clinical-event'):(clearing?'data-trauma-event':'data-clear-trauma-event');document.querySelector(`[${attribute}="${event}"]`)?.focus({preventScroll:true});});
}
